static void qpk_camera_convert(FAR const struct qpk_camera_s *camera,
                               FAR const uint8_t *raw,
                               FAR uint16_t *rgb565)
{
  int x;
  int y;

  for (y = 0; y < QPK_CAMERA_VIEW_HEIGHT; y++)
    {
      FAR const uint8_t *even = raw + y * 2 * QPK_CAMERA_RAW_WIDTH;
      FAR const uint8_t *odd = even + QPK_CAMERA_RAW_WIDTH;
      FAR uint16_t *output = rgb565 + y * QPK_CAMERA_VIEW_WIDTH;

      for (x = 0; x < QPK_CAMERA_VIEW_WIDTH; x++)
        {
          int source_x = x * 2;
          uint16_t blue = camera->blue_lut[even[source_x]];
          uint16_t green =
            (even[source_x + 1] + odd[source_x] + 1) / 2;
          uint16_t red = camera->red_lut[odd[source_x + 1]];

          /* SC2336 delivers unprocessed Bayer data, so there is no ISP auto
           * white balance.  Apply a mild daylight gain to the red and blue
           * samples to remove the green cast without changing luminance.
           */

          output[x] = ((uint16_t)(red & 0xf8) << 8) |
                      ((uint16_t)(green & 0xfc) << 3) | (blue >> 3);
        }
    }
}

