static JSValue js_camera_start(JSContext *context,
                               JSValueConst this_value,
                               int argc, JSValueConst *argv)
{
  int x;
  int y;
  int ret;

  (void)this_value;
  x = qpk_arg_int(context, argc, argv, 0, 124);
  y = qpk_arg_int(context, argc, argv, 1, 12);
  ret = qpk_camera_start(x, y);
  if (ret < 0)
    {
