}

TEST_CASE("TEST esp_cam on ov5647", "[csi][camera][ov5647]")
{
    new_buffer_count = 0;
    trans_finished_count = 0;

    size_t frame_buffer_size = TEST_MIPI_CSI_DISP_HRES *
                               TEST_MIPI_DSI_DISP_VRES *
                               TEST_RGB565_BITS_PER_PIXEL / 8;

