    size_t frame_buffer_alignment = 0;
    TEST_ESP_OK(esp_cache_get_alignment(0, &frame_buffer_alignment));
    void *frame_buffer = heap_caps_aligned_calloc(frame_buffer_alignment, 1, frame_buffer_size,
