static int esp_mipi_csi_isp_init(FAR struct esp_mipi_csi_s *priv)
{
  hal_utils_clk_div_t clk_div;
  esp_err_t err;

  priv->isp = ISP_LL_GET_HW(0);
  memset(&clk_div, 0, sizeof(clk_div));
  clk_div.integer = 2;

  err = esp_clk_tree_enable_src((soc_module_clk_t)ISP_CLK_SRC_DEFAULT,
                                true);
  if (err != ESP_OK)
    {
      verr("CSI: enable ISP clock source failed: %d\n", (int)err);
      priv->isp = NULL;
      return -EIO;
    }

  PERIPH_RCC_ATOMIC()
    {
      isp_ll_enable_module_clock(priv->isp, true);
      isp_ll_reset_module_clock(priv->isp);
      isp_ll_select_clk_source(priv->isp, ISP_CLK_SRC_DEFAULT);
      isp_ll_set_clock_div(priv->isp, &clk_div);
    }

  isp_ll_init(priv->isp);
  isp_ll_clk_enable(priv->isp, true);
  isp_ll_set_input_data_source(priv->isp, ISP_INPUT_DATA_SOURCE_CSI);
  isp_ll_enable_line_start_packet_exist(priv->isp, false);
  isp_ll_enable_line_end_packet_exist(priv->isp, false);
  isp_ll_set_bayer_mode(priv->isp, COLOR_RAW_ELEMENT_ORDER_BGGR);
  isp_ll_shadow_set_mode(priv->isp,
                         ISP_SHADOW_MODE_UPDATE_ONLY_NEXT_VSYNC);
  isp_ll_enable(priv->isp, false);
  return OK;
}

static int esp_mipi_csi_isp_configure(FAR struct esp_mipi_csi_s *priv,
                                      uint32_t pixelformat)
{
  bool valid;

  isp_ll_enable(priv->isp, false);
  valid = isp_ll_set_input_data_color_format(priv->isp, ISP_COLOR_RAW8);
  if (!valid)
    {
      return -EINVAL;
    }

  isp_ll_set_intput_data_v_row_num(priv->isp, ESP_MIPI_CSI_HEIGHT);
  isp_ll_set_bayer_mode(priv->isp, COLOR_RAW_ELEMENT_ORDER_BGGR);
  isp_ll_set_byte_swap(priv->isp, false);

  if (pixelformat == IMGDATA_PIX_FMT_RGB565)
    {
      valid = isp_ll_set_output_data_color_format(priv->isp,
                                                   ISP_COLOR_RGB565);
      if (!valid)
        {
          return -EINVAL;
        }

      /* Follow Espressif's RAW8 -> RGB565 ISP pipeline.  The RGB565 output
       * path internally traverses RGB/YUV conversion stages, so configure
       * their standard and range even though the external format is RGB.
       */

      isp_ll_set_intput_data_h_pixel_num(priv->isp, ESP_MIPI_CSI_WIDTH);
      isp_ll_yuv_set_std(priv->isp, ISP_YUV_CONV_STD_BT601);
      isp_ll_yuv_set_range(priv->isp, ISP_COLOR_RANGE_FULL);
      priv->frame_size = ESP_MIPI_CSI_RGB565_FRAME_SIZE;
      priv->isp_enabled = true;
    }
  else if (pixelformat == IMGDATA_PIX_FMT_SBGGR8)
    {
      valid = isp_ll_set_output_data_color_format(priv->isp,
                                                   ISP_COLOR_RAW8);
      if (!valid)
        {
          return -EINVAL;
        }

      /* In bypass mode H size is the number of 32-bit RAW words per line. */

      isp_ll_set_intput_data_h_pixel_num(priv->isp,
                                         ESP_MIPI_CSI_WIDTH / 4);
      priv->frame_size = ESP_MIPI_CSI_RAW_FRAME_SIZE;
      priv->isp_enabled = false;
    }
  else
    {
      return -EINVAL;
    }

  priv->pixelformat = pixelformat;
  return OK;
}

