static void qpk_dialog_close(lv_event_t *e)
{
  lv_obj_t *shade = lv_event_get_user_data(e);

  if (g_desktop.dialog == shade)
    {
      g_desktop.dialog = NULL;
    }

  lv_obj_delete(shade);
}

static void qpk_show_dialog(const char *text)
{
  lv_obj_t *shade;
