    PPA_FILL_COLOR_MODE_RGB888 = ESP_COLOR_FOURCC_BGR24,            /*!< PPA fill color mode: RGB888 */
    PPA_FILL_COLOR_MODE_RGB565 = ESP_COLOR_FOURCC_RGB16,            /*!< PPA fill color mode: RGB565 */
