static inline void vQueueDeleteWithCaps(QueueHandle_t queue)
{
  esp_os_queue_delete_with_caps(queue);
}

static inline SemaphoreHandle_t xSemaphoreCreateBinaryWithCaps(uint32_t caps)
{
  SemaphoreHandle_t sem;

  sem = heap_caps_malloc(sizeof(*sem), caps);
  if (sem != NULL)
    {
      nxsem_init(sem, 0, 0);
    }

  return sem;
}

static inline BaseType_t xSemaphoreTake(SemaphoreHandle_t sem,
                                        TickType_t ticks)
{
  int ret;

  if (ticks == 0)
    {
      ret = nxsem_trywait(sem);
    }
  else if (ticks == portMAX_DELAY)
    {
      ret = nxsem_wait_uninterruptible(sem);
    }
  else
    {
      ret = nxsem_tickwait_uninterruptible(sem, ticks);
    }

  return ret == OK ? pdTRUE : pdFALSE;
}

static inline BaseType_t xSemaphoreGive(SemaphoreHandle_t sem)
{
  return nxsem_post(sem) == OK ? pdTRUE : pdFALSE;
