  REGI2C_WRITE_MASK(I2C_BIAS, I2C_BIAS_DREG_1P1_PVT, 10);
  rtc_clk_xtal_freq_update(SOC_XTAL_FREQ_40M);

  {
    rtc_cpu_freq_config_t cpu_config;

    if (rtc_clk_cpu_freq_mhz_to_config(90, &cpu_config))
      {
        rtc_clk_cpu_freq_set_config(&cpu_config);
      }
  }

#  ifdef CONFIG_ESPRESSIF_SPIRAM
  {
    struct esp_ldo_config_t psram_ldo = {0};

    psram_ldo.chan_id = 2;
    psram_ldo.voltage_mv = 1800;

    ret = esp_ldo_channel_acquire(&psram_ldo);
    if (ret == ESP_OK)
      {
        ret = esp_psram_chip_init();
        if (ret == ESP_OK)
